package com.werewolf.community;
import com.baomidou.mybatisplus.core.toolkit.Wrappers;
import com.werewolf.community.mapper.*;
import com.werewolf.common.*;
import com.werewolf.media.MediaService;
import com.werewolf.user.UserDirectoryService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.LocalDateTime;
import java.util.*;
@Service
public class CommunityService {
 private final PostMapper posts;private final PostImageMapper images;private final PostLikeMapper likes;private final PostCommentMapper comments;private final UserDirectoryService users;private final MediaService media;private final TransactionTemplate tx;
 public CommunityService(PostMapper p,PostImageMapper i,PostLikeMapper l,PostCommentMapper c,UserDirectoryService u,MediaService m,PlatformTransactionManager tm){posts=p;images=i;likes=l;comments=c;users=u;media=m;tx=new TransactionTemplate(tm);}
 public record View(Long id,UserDirectoryService.PublicUser author,String content,List<String> mediaIds,long likeCount,long commentCount,boolean liked,LocalDateTime createdAt){}
 public record CommentView(Long id,Long postId,UserDirectoryService.PublicUser author,String content,LocalDateTime createdAt){}
 public record Feed<T>(List<T> items,Long nextBeforeId,boolean hasMore){}
 private Post require(Long id){var p=posts.selectById(id);if(p==null||Boolean.TRUE.equals(p.getDeleted()))throw BizException.of(ErrorCode.NOT_FOUND,"动态不存在或已删除");return p;}
 private void key(String key){if(key==null||!key.matches("[A-Za-z0-9_-]{8,64}"))throw BizException.of(ErrorCode.BAD_REQUEST,"请求标识不合法");}
 private String content(String value,int max,boolean blank){String s=value==null?"":value.strip();if((!blank&&s.isBlank())||s.codePointCount(0,s.length())>max)throw BizException.of(ErrorCode.BAD_REQUEST,"内容不能为空或超过"+max+"字");return s;}
 private List<String> mediaIds(Long id){return images.selectList(Wrappers.<PostImage>lambdaQuery().eq(PostImage::getPostId,id).orderByAsc(PostImage::getSortOrder)).stream().map(PostImage::getMediaId).toList();}
 private View view(Post p,Long uid){return new View(p.getId(),users.profile(p.getAuthorId()),p.getContent(),mediaIds(p.getId()),likes.selectCount(Wrappers.<PostLike>lambdaQuery().eq(PostLike::getPostId,p.getId())),comments.selectCount(Wrappers.<PostComment>lambdaQuery().eq(PostComment::getPostId,p.getId()).eq(PostComment::getDeleted,false)),likes.selectCount(Wrappers.<PostLike>lambdaQuery().eq(PostLike::getPostId,p.getId()).eq(PostLike::getUserId,uid))>0,p.getCreatedAt());}
 public View get(Long uid,Long id){return view(require(id),uid);}
 public Feed<View> feed(Long uid,Long author,Long before,int limit){if(limit<1||limit>30||before!=null&&before<=0||author!=null&&author<=0)throw BizException.of(ErrorCode.BAD_REQUEST);var q=Wrappers.<Post>lambdaQuery().eq(Post::getDeleted,false);if(author!=null)q.eq(Post::getAuthorId,author);if(before!=null)q.lt(Post::getId,before);var rows=posts.selectList(q.orderByDesc(Post::getId).last("LIMIT "+(limit+1)));boolean more=rows.size()>limit;if(more)rows=rows.subList(0,limit);return new Feed<>(rows.stream().map(p->view(p,uid)).toList(),rows.isEmpty()?null:rows.get(rows.size()-1).getId(),more);}
 public synchronized View create(Long uid,String requestId,String text,List<String> requestedImages){key(requestId);String value=content(text,2000,true);List<String> ids=requestedImages==null?List.of():List.copyOf(requestedImages);if(ids.size()>9||new HashSet<>(ids).size()!=ids.size()||value.isBlank()&&ids.isEmpty())throw BizException.of(ErrorCode.BAD_REQUEST,"动态需有文字或图片，最多9张且不可重复");return tx.execute(s->{var old=posts.selectOne(Wrappers.<Post>lambdaQuery().eq(Post::getAuthorId,uid).eq(Post::getClientRequestId,requestId));if(old!=null){if(Boolean.TRUE.equals(old.getDeleted())||!value.equals(old.getContent())||!ids.equals(mediaIds(old.getId())))throw BizException.of(ErrorCode.BAD_REQUEST,"请求标识已用于其他动态");return view(old,uid);}for(String id:ids){var asset=media.require(id);if(!uid.equals(asset.getOwnerId())||!"PRIVATE".equals(asset.getPurpose()))throw BizException.of(ErrorCode.FORBIDDEN,"只能使用自己上传的动态图片");}var p=new Post();p.setAuthorId(uid);p.setClientRequestId(requestId);p.setContent(value);p.setDeleted(false);p.setCreatedAt(LocalDateTime.now());posts.insert(p);for(int i=0;i<ids.size();i++){var image=new PostImage();image.setPostId(p.getId());image.setMediaId(ids.get(i));image.setSortOrder(i);images.insert(image);}return view(p,uid);});}
 public synchronized void delete(Long uid,Long id){tx.executeWithoutResult(s->{var p=posts.selectById(id);if(p==null)throw BizException.of(ErrorCode.NOT_FOUND);if(!uid.equals(p.getAuthorId()))throw BizException.of(ErrorCode.FORBIDDEN,"只能删除自己的动态");if(!Boolean.TRUE.equals(p.getDeleted())){p.setDeleted(true);posts.updateById(p);}});}
 public synchronized View like(Long uid,Long id,boolean on){return tx.execute(s->{var p=require(id);var q=Wrappers.<PostLike>lambdaQuery().eq(PostLike::getPostId,id).eq(PostLike::getUserId,uid);var old=likes.selectOne(q);if(on&&old==null){var l=new PostLike();l.setPostId(id);l.setUserId(uid);l.setCreatedAt(LocalDateTime.now());likes.insert(l);}else if(!on&&old!=null)likes.deleteById(old.getId());return view(p,uid);});}
 private CommentView commentView(PostComment c){return new CommentView(c.getId(),c.getPostId(),users.profile(c.getAuthorId()),c.getContent(),c.getCreatedAt());}
 public Feed<CommentView> comments(Long uid,Long id,Long before,int limit){require(id);if(limit<1||limit>50||before!=null&&before<=0)throw BizException.of(ErrorCode.BAD_REQUEST);var q=Wrappers.<PostComment>lambdaQuery().eq(PostComment::getPostId,id).eq(PostComment::getDeleted,false);if(before!=null)q.lt(PostComment::getId,before);var rows=comments.selectList(q.orderByDesc(PostComment::getId).last("LIMIT "+(limit+1)));boolean more=rows.size()>limit;if(more)rows=new ArrayList<>(rows.subList(0,limit));Collections.reverse(rows);return new Feed<>(rows.stream().map(this::commentView).toList(),rows.isEmpty()?null:rows.get(0).getId(),more);}
 public synchronized CommentView comment(Long uid,Long id,String requestId,String text){key(requestId);String value=content(text,500,false);return tx.execute(s->{require(id);var old=comments.selectOne(Wrappers.<PostComment>lambdaQuery().eq(PostComment::getAuthorId,uid).eq(PostComment::getClientRequestId,requestId));if(old!=null){if(Boolean.TRUE.equals(old.getDeleted())||!id.equals(old.getPostId())||!value.equals(old.getContent()))throw BizException.of(ErrorCode.BAD_REQUEST,"请求标识已用于其他评论");return commentView(old);}var c=new PostComment();c.setPostId(id);c.setAuthorId(uid);c.setClientRequestId(requestId);c.setContent(value);c.setDeleted(false);c.setCreatedAt(LocalDateTime.now());comments.insert(c);return commentView(c);});}
 public synchronized void deleteComment(Long uid,Long postId,Long id){tx.executeWithoutResult(s->{require(postId);var c=comments.selectById(id);if(c==null||!postId.equals(c.getPostId()))throw BizException.of(ErrorCode.NOT_FOUND);if(!uid.equals(c.getAuthorId()))throw BizException.of(ErrorCode.FORBIDDEN,"只能删除自己的评论");c.setDeleted(true);comments.updateById(c);});}
}
